VALUES ('doc-09-mitre-attack-p0-13460', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-18T18:25:08.460Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SynAck](https://attack.mitre.org/software/S0242) lists all the keyboard layouts installed on the victim’s system using GetKeyboardLayoutList API and checks against a hardcoded language code list. If a match if found, SynAck sleeps for 300 seconds and then exits without encrypting files.(Citation: SecureList SynAck Doppelgänging May 2018) ", "external_references": [{"description": "Ivanov, A. et al. (2018, May 7). SynAck targeted ransomware uses the Doppelgänging technique. Retrieved May 22, 2018.", "source_name": "SecureList SynAck Doppelgänging May 2018", "url": "https://securelist.com/synack-targeted-ransomware-uses-the-doppelganging-technique/85431/"}], "id": "relationship--cfed60a3-c288-4c12-bfe2-2c0234a3cfa7", "modified": "2026-04-29T14:23:06.210Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--04227b24-7817-4de1-9050-b7b1b57f5866", "spec_version": "2.1", "target_ref": "attack-pattern--c1b68a96-3c48-49ea-a6c0-9b27359f9c19", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13460', 0, 101, '09-mitre-attack', 'retrieved', '5BE37BC6EC81A35D63B50B633F2053572C0BA46AE4B2CB759E2714DC84B7AA5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
