VALUES ('doc-09-mitre-attack-p0-13501', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:12:38.146Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has utilized Go libraries to include Garble to obfuscate code.(Citation: Picus Security BRICKSTORM UNC5221 October 2025)(Citation: Google BRICKSTORM September 2025)", "external_references": [{"description": "Huseyin Can Yuceel. (2025, October 1). BRICKSTORM Malware: UNC5221 Targets Tech and Legal Sectors in the United States. Retrieved April 16, 2026.", "source_name": "Picus Security BRICKSTORM UNC5221 October 2025", "url": "https://www.picussecurity.com/resource/blog/brickstorm-malware-unc5221-targets-tech-and-legal-sectors-in-the-united-states"}, {"description": "Sarah Yoder, John Wolfram, Ashley Pearson, Doug Bienstock, Josh Madeley, Josh Murchie, Brad Slaybaugh, Matt Lin, Geoff Carstairs, Austin Larsen. (2025, September 24). Another BRICKSTORM: Stealthy Backdoor Enabling Espionage into Tech and Legal Sectors. Retrieved April 16, 2026.", "source_name": "Google BRICKSTORM September 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/brickstorm-espionage-campaign"}], "id": "relationship--130768d0-0f98-4a1b-b4bb-34c5e372cda1", "modified": "2026-04-29T14:23:05.930Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13501', 0, 129, '09-mitre-attack', 'retrieved', 'FFBD91B8AF96ACBDB1E1FCAB24D60BF0AB6B2E219BC351C441E81937FBFDC9BE', 'v1', '{"source_id": "09-mitre-