VALUES ('doc-09-mitre-attack-p0-13502', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T23:45:12.027Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has uploaded files from the victim system to C2 servers.(Citation: CrowdStrike BRICKSTORM WARP PANDA UNC5221 December 2025)(Citation: CISA BRICKSTORM UNC5221 AR25-338A February 2026)(Citation: Picus Security BRICKSTORM UNC5221 October 2025)(Citation: Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024)(Citation: NVISO BRICKSTORM April 2025)(Citation: Resecurity UNC5221 BRICKSTORM F5 Big-IP October 2025)(Citation: Google BRICKSTORM September 2025)", "external_references": [{"description": "CrowdStrike. (2025, December 4). Unveiling WARP PANDA: A New Sophisticated China-Nexus Adversary. Retrieved April 16, 2026.", "source_name": "CrowdStrike BRICKSTORM WARP PANDA UNC5221 December 2025", "url": "https://www.crowdstrike.com/en-us/blog/warp-panda-cloud-threats/"}, {"description": "DHS/CISA. (2026, February 11). AR25-338A: BRICKSTORM Backdoor. Retrieved April 16, 2026.", "source_name": "CISA BRICKSTORM UNC5221 AR25-338A February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-338a"}, {"description": "Huseyin Can Yuceel. (2025, October 1). BRICKSTORM Malware: UNC5221 Targets Tech and Legal Sectors in the United States. Retrieved April 16, 2026.", "source_name": "Picus Security BRICKSTORM UNC5221 October 2025", "url": "https://www.picussecurity.com/resource/blog/brickstorm-malware-unc5221-targets-tech-and-legal-sectors-in-the-united-states"}, {"description": "Matt Lin, Austin Larsen, John Wolfram, Ashley Pearson, Josh Murchie, Lukasz Lamparski, Joseph Pisano, Ryan Hall, Ron Craft, Shawn Crew, Billy Wong, Tyler McLellan. (2024, April 4). Cutting Edge, Part 4: Ivanti Connect Secure VPN Post-Exploitation Lateral Movement Case Studies. Retrieved April 16, 2026.", "source_name": "Google UNC5221 BRICKSTORM SPAWNCHIMERA April 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/ivanti-post-exploitation-lateral-movement"}, {"description": "NVISO Incident Response. (2025, April 1). BRICKSTORM Backdoor Analysis: A Persistent Espionage Threat to European Industries. Retrieved April 16, 2026.", "source_name": "NVISO BRICKSTORM April 2025", "url": "https://blog.nviso.eu/wp-content/uploads/2025/04/NVISO-BRICKSTORM-Report.pdf"}, {"description": "Resecurity Threat Intelligence & Incident Analysis. (2025, October 22). F5 BIG-IP Source Code Leak Tied to State-Linked Campaigns Using BRICKSTORM Backdoor. Retrieved April 16, 2026.", "source_name": "Resecurity UNC5221 BRICKSTORM F5 Big-IP October 2025", "url": "https://www.resecurity.com/blog/article/f5-big-ip-source-code-leak-tied-to-state-linked-campaigns-using-brickstorm-backdoor"}, {"description": "Sarah Yoder, John Wolfram, Ashley Pearson, Doug Bienstock, Josh Madeley, Josh Murchie, Brad Slaybaugh, Matt Lin, Geoff Carstairs, Austin Larsen. (2025, September 24). Another BRICKSTORM: Stealthy Backdoor Enabling Espionage into Tech and Legal Sectors. Retrieved April 16, 2026.", "source_name": "Google BRICKSTORM September 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/brickstorm-espionage-campaign"}], "id": "relationship--152e4b86-e51c-4470-84ff-5b6985b1c660", "modified": "2026-04-29T14:23:05.933Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13502', 0, 325, '09-mitre-attack', 'retrieved', 'D5302EA568CA5C23DFD6DB9E9132A13B0ED1FEB84A1A3A654BDA69DB0BF124DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
