VALUES ('doc-09-mitre-attack-p0-13505', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:09:20.003Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has copied itself to the `usr/sbin/` folder.(Citation: CISA BRICKSTORM UNC5221 AR25-338A February 2026)", "external_references": [{"description": "DHS/CISA. (2026, February 11). AR25-338A: BRICKSTORM Backdoor. Retrieved April 16, 2026.", "source_name": "CISA BRICKSTORM UNC5221 AR25-338A February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-338a"}], "id": "relationship--44bc8e60-84bd-4b19-8b2f-acb34c50179d", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--cc36eeae-2209-4e63-89d3-c97e19edf280", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13505', 0, 65, '09-mitre-attack', 'retrieved', '4DE365CA7360858B6F8A0C5BE57D8E2B66B97606AA57D18DB0A9E62D322E5C7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
