VALUES ('doc-09-mitre-attack-p0-13506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:04:58.320Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has the ability to check if it is running as an active child process through the detection of a specific environment variable.(Citation: CISA BRICKSTORM UNC5221 AR25-338A February 2026)", "external_references": [{"description": "DHS/CISA. (2026, February 11). AR25-338A: BRICKSTORM Backdoor. Retrieved April 16, 2026.", "source_name": "CISA BRICKSTORM UNC5221 AR25-338A February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-338a"}], "id": "relationship--59318d61-e9d9-4edc-8965-9d6b1c2e633f", "modified": "2026-04-29T14:23:06.047Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13506', 0, 80, '09-mitre-attack', 'retrieved', '84E3E1B9EE6D9F55CA6943BCE1D0E199814E6B3C97C2FCAD14240CF38EF3121D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
