INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-13508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:04:17.675Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has utilized XOR cipher encryption to hide key strings within their code, to include IPv4 addresses of public DNS-over-HTTPS (DOH) servers.(Citation: CISA BRICKSTORM UNC5221 AR25-338A February 2026)", "external_references": [{"description": "DHS/CISA. (2026, February 11). AR25-338A: BRICKSTORM Backdoor. Retrieved April 16, 2026.", "source_name": "CISA BRICKSTORM UNC5221 AR25-338A February 2026", "url": "https://www.cisa.gov/news-events/analysis-reports/ar25-338a"}], "id": "relationship--62890054-ce8d-479e-8331-eab58bed6ede", "modified": "2026-04-29T14:23:06.059Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13508', 0, 79, '09-mitre-attack', 'retrieved', '4C712184D3DBB43C7F482988BBFF59B71C9F9100F1A8B164D0F8FF70FF576C7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
