VALUES ('doc-09-mitre-attack-p0-13516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:14:34.608Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has embedded delayed-start logic that attempts to circumvent detection for long-term persistence.(Citation: Picus Security BRICKSTORM UNC5221 October 2025)(Citation: NVISO BRICKSTORM April 2025) [BRICKSTORM](https://attack.mitre.org/software/S9015) has been observed configured with a “delay” timer built-in that waited for a hard-coded date months in the future before beginning to beacon to the configured C2 domain.(Citation: Google BRICKSTORM September 2025)", "external_references": [{"description": "Huseyin Can Yuceel. (2025, October 1). BRICKSTORM Malware: UNC5221 Targets Tech and Legal Sectors in the United States. Retrieved April 16, 2026.", "source_name": "Picus Security BRICKSTORM UNC5221 October 2025", "url": "https://www.picussecurity.com/resource/blog/brickstorm-malware-unc5221-targets-tech-and-legal-sectors-in-the-united-states"}, {"description": "NVISO Incident Response. (2025, April 1). BRICKSTORM Backdoor Analysis: A Persistent Espionage Threat to European Industries. Retrieved April 16, 2026.", "source_name": "NVISO BRICKSTORM April 2025", "url": "https://blog.nviso.eu/wp-content/uploads/2025/04/NVISO-BRICKSTORM-Report.pdf"}, {"description": "Sarah Yoder, John Wolfram, Ashley Pearson, Doug Bienstock, Josh Madeley, Josh Murchie, Brad Slaybaugh, Matt Lin, Geoff Carstairs, Austin Larsen. (2025, September 24). Another BRICKSTORM: Stealthy Backdoor Enabling Espionage into Tech and Legal Sectors. Retrieved April 16, 2026.", "source_name": "Google BRICKSTORM September 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/brickstorm-espionage-campaign"}], "id": "relationship--ac12a059-4777-4f73-933d-832605de696e", "modified": "2026-04-29T14:23:06.159Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--a1df809c-7d0e-459f-8fe5-25474bab770b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13516', 0, 192, '09-mitre-attack', 'retrieved', 'BE3CC28E4E5F65555972BAFB43D8843B2B78A2E19F1427E9B77E9535D751E113', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
