VALUES ('doc-09-mitre-attack-p0-13517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T00:27:53.398Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BRICKSTORM](https://attack.mitre.org/software/S9015) has utilized DNS services sslip.io and nip.io to resolve C2 IP addresses.(Citation: Google BRICKSTORM September 2025) ", "external_references": [{"description": "Sarah Yoder, John Wolfram, Ashley Pearson, Doug Bienstock, Josh Madeley, Josh Murchie, Brad Slaybaugh, Matt Lin, Geoff Carstairs, Austin Larsen. (2025, September 24). Another BRICKSTORM: Stealthy Backdoor Enabling Espionage into Tech and Legal Sectors. Retrieved April 16, 2026.", "source_name": "Google BRICKSTORM September 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/brickstorm-espionage-campaign"}], "id": "relationship--b804627f-f89d-442d-bcea-15c21b1508b6", "modified": "2026-04-29T14:23:06.176Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0450ed20-e9a7-4799-b601-2f2710300796", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13517', 0, 94, '09-mitre-attack', 'retrieved', '4B7228041D5E8E4C0DD8D58565779B4918081583F05785DC286EDE235FB4EE94', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
