VALUES ('doc-09-mitre-attack-p0-13535', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-25T16:54:39.707Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AcidRain](https://attack.mitre.org/software/S1125) reboots the target system once the various wiping processes are complete.(Citation: AcidRain JAGS 2022)", "external_references": [{"description": "Juan Andres Guerrero-Saade and Max van Amerongen, SentinelOne. (2022, March 31). AcidRain | A Modem Wiper Rains Down on Europe. Retrieved March 25, 2024.", "source_name": "AcidRain JAGS 2022", "url": "https://www.sentinelone.com/labs/acidrain-a-modem-wiper-rains-down-on-europe/"}], "id": "relationship--098c0f13-e56f-43ff-8fee-0cce9d771092", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--04cecafd-cb5f-4daf-aa1f-73899116c4a2", "spec_version": "2.1", "target_ref": "attack-pattern--ff73aa03-0090-4464-83ac-f89e233c02bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13535', 0, 76, '09-mitre-attack', 'retrieved', 'C5A7FFE423A0B087A2A6D0EC08895034987383520F544C59F0E4137601B2B5EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
