VALUES ('doc-09-mitre-attack-p0-13536', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-25T16:45:41.768Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AcidRain](https://attack.mitre.org/software/S1125) performs an in-depth wipe of the target filesystem and various attached storage devices through either a data overwrite or calling various IOCTLS to erase it.(Citation: AcidRain JAGS 2022)", "external_references": [{"description": "Juan Andres Guerrero-Saade and Max van Amerongen, SentinelOne. (2022, March 31). AcidRain | A Modem Wiper Rains Down on Europe. Retrieved March 25, 2024.", "source_name": "AcidRain JAGS 2022", "url": "https://www.sentinelone.com/labs/acidrain-a-modem-wiper-rains-down-on-europe/"}], "id": "relationship--28d36206-062f-42be-93a1-f9cf2910c3c4", "modified": "2026-04-29T14:23:05.960Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--04cecafd-cb5f-4daf-aa1f-73899116c4a2", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13536', 0, 90, '09-mitre-attack', 'retrieved', 'CCFB78D16BEDC7438CD92A7078CDC8710FC2F654ED6951E04B28ADC98EDAD487', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
