VALUES ('doc-09-mitre-attack-p0-13697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-14T17:34:58.822Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Stuxnet](https://attack.mitre.org/software/S0603) injects an entire DLL into an existing, newly created, or preselected trusted process.(Citation: Nicolas Falliere, Liam O Murchu, Eric Chien February 2011)", "external_references": [{"description": "Nicolas Falliere, Liam O Murchu, Eric Chien 2011, February W32.Stuxnet Dossier (Version 1.4) Retrieved November 17, 2024.", "source_name": "Nicolas Falliere, Liam O Murchu, Eric Chien February 2011", "url": "https://docs.broadcom.com/doc/security-response-w32-stuxnet-dossier-11-en"}], "id": "relationship--7307a870-2d74-4e46-9ba0-8fb83d598cfb", "modified": "2026-04-29T14:23:06.082Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--088f1d6e-0783-47c6-9923-9c79b2af43d4", "spec_version": "2.1", "target_ref": "attack-pattern--f4599aa0-4f85-4a32-80ea-fc39dc965945", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13697', 0, 83, '09-mitre-attack', 'retrieved', '4CA99C38D1DB399FE485BB6E8C1BF2C441DB330F2460047F67D1E707B4269AD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
