VALUES ('doc-09-mitre-attack-p0-13698', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-14T23:23:56.191Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Stuxnet](https://attack.mitre.org/software/S0603) encodes the payload of system information sent to the command and control servers using a one byte 0xFF XOR key. [Stuxnet](https://attack.mitre.org/software/S0603) also uses a 31-byte long static byte string to XOR data sent to command and control servers. The servers use a different static key to encrypt replies to the implant.(Citation: Nicolas Falliere, Liam O Murchu, Eric Chien February 2011)", "external_references": [{"description": "Nicolas Falliere, Liam O Murchu, Eric Chien 2011, February W32.Stuxnet Dossier (Version 1.4) Retrieved November 17, 2024.", "source_name": "Nicolas Falliere, Liam O Murchu, Eric Chien February 2011", "url": "https://docs.broadcom.com/doc/security-response-w32-stuxnet-dossier-11-en"}], "id": "relationship--73fa4b5d-e75f-4050-b7aa-d003b3a31bf3", "modified": "2026-04-29T14:23:06.084Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--088f1d6e-0783-47c6-9923-9c79b2af43d4", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13698', 0, 121, '09-mitre-attack', 'retrieved', 'E96AAF786594042DE8308606B588AFBB17FB3DE784C9F419C14084ABB17DD7E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
