VALUES ('doc-09-mitre-attack-p0-13731', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T12:49:19.799Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IronWind](https://attack.mitre.org/software/S9029) can list installed software on targeted hosts.(Citation: Check Point Wirte NOV 2024)", "external_references": [{"description": "Check Point. (2024, November 12). Hamas-affiliated Threat Actor WIRTE Continues its Middle East Operations and Moves to Disruptive Activity. Retrieved April 20, 2026.", "source_name": "Check Point Wirte NOV 2024", "url": "https://research.checkpoint.com/2024/hamas-affiliated-threat-actor-expands-to-disruptive-activity/"}], "id": "relationship--c78ed1f7-5a62-4153-8230-df01164232f4", "modified": "2026-04-29T14:23:06.198Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--089aa00a-99ac-46b4-9cf8-4224d463566d", "spec_version": "2.1", "target_ref": "attack-pattern--e3b6daca-e963-4a69-aee6-ed4fd653ad58", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13731', 0, 75, '09-mitre-attack', 'retrieved', 'CE1F532E75221730A3AA9A6876253B6CF45421B4D7295B49C1418ACED8F33E0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
