VALUES ('doc-09-mitre-attack-p0-13732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T12:53:50.176Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IronWind](https://attack.mitre.org/software/S9029) has used a .NET DLL named \"exit-DN4-core.dll\" to terminate malicious processes running on victim''s systems.(Citation: Check Point Wirte NOV 2024)", "external_references": [{"description": "Check Point. (2024, November 12). Hamas-affiliated Threat Actor WIRTE Continues its Middle East Operations and Moves to Disruptive Activity. Retrieved April 20, 2026.", "source_name": "Check Point Wirte NOV 2024", "url": "https://research.checkpoint.com/2024/hamas-affiliated-threat-actor-expands-to-disruptive-activity/"}], "id": "relationship--e1947d14-2a8a-4f22-90dd-75a351c039bd", "modified": "2026-04-29T14:23:06.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--089aa00a-99ac-46b4-9cf8-4224d463566d", "spec_version": "2.1", "target_ref": "attack-pattern--799ace7f-e227-4411-baa0-8868704f2a69", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13732', 0, 83, '09-mitre-attack', 'retrieved', 'DD94D0B888F0D4AEA41B98ED67198612283E73541FB37A3D645978A966B6371F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
