VALUES ('doc-09-mitre-attack-p0-13733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Downdelph](https://attack.mitre.org/software/S0134) inserts pseudo-random characters between each original character during encoding of C2 network requests, making it difficult to write signatures on them.(Citation: ESET Sednit Part 3)", "external_references": [{"description": "ESET. (2016, October). En Route with Sednit - Part 3: A Mysterious Downloader. Retrieved November 21, 2016.", "source_name": "ESET Sednit Part 3", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part3.pdf"}], "id": "relationship--0e27ebb3-2d48-48f6-ab99-968c0a992c61", "modified": "2026-04-29T14:23:05.922Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08d20cd2-f084-45ee-8558-fa6ef5a18519", "spec_version": "2.1", "target_ref": "attack-pattern--f7c0689c-4dbd-489b-81be-7cb7c7079ade", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13733', 0, 81, '09-mitre-attack', 'retrieved', '378C37D598A852744E3F1B1F2E4EE7C6315D3CD6C5ADB8C78A40C541CB721562', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
