VALUES ('doc-09-mitre-attack-p0-13745', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-21T21:52:32.361Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) uses dynamically linked shared libraries (`.so` files) to execute additional functionality using `dlopen()` and `dlsym()`.(Citation: RotaJakiro 2021 netlab360 analysis)", "external_references": [{"description": " Alex Turing, Hui Wang. (2021, April 28). RotaJakiro: A long live secret backdoor with 0 VT detection. Retrieved June 14, 2023.", "source_name": "RotaJakiro 2021 netlab360 analysis", "url": "https://blog.netlab.360.com/stealth_rotajakiro_backdoor_en/"}], "id": "relationship--9da28d8d-5111-491a-9557-bee7004fc3a6", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--0a5231ec-41af-4a35-83d0-6bdf11f28c65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13745', 0, 80, '09-mitre-attack', 'retrieved', '88CE00059E514926482F8FF0D1044E9B22568B26ADF1EB2CB82447BCF5493F5E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
