VALUES ('doc-09-mitre-attack-p0-13746', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-12T21:31:42.352Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) uses a custom binary protocol over TCP port 443.(Citation: netlab360 rotajakiro vs oceanlotus)", "external_references": [{"description": "Alex Turing. (2021, May 6). RotaJakiro, the Linux version of the OceanLotus. Retrieved June 14, 2023.", "source_name": "netlab360 rotajakiro vs oceanlotus", "url": "https://blog.netlab.360.com/rotajakiro_linux_version_of_oceanlotus/"}], "id": "relationship--af74a9b1-6c74-45b6-a21d-38686afb202c", "modified": "2026-04-29T14:23:06.164Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13746', 0, 68, '09-mitre-attack', 'retrieved', 'B8EDC3E19BF446F949632D0D4F751867A98BDA5F4EF10A2C20391F69EB099071', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
