VALUES ('doc-09-mitre-attack-p0-13747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-12T15:26:33.430Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) uses a custom binary protocol using a type, length, value format over TCP.(Citation: netlab360 rotajakiro vs oceanlotus)", "external_references": [{"description": "Alex Turing. (2021, May 6). RotaJakiro, the Linux version of the OceanLotus. Retrieved June 14, 2023.", "source_name": "netlab360 rotajakiro vs oceanlotus", "url": "https://blog.netlab.360.com/rotajakiro_linux_version_of_oceanlotus/"}], "id": "relationship--b7f887ee-e0e5-4cab-9898-6dfed9b86f31", "modified": "2026-04-29T14:23:06.176Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--c21d5a77-d422-4a69-acd7-2c53c1faa34b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13747', 0, 72, '09-mitre-attack', 'retrieved', 'BBB7C329634ACE96E2663C21B9F108AE6A00E3C58ED12FDF6C74EE54834CBE74', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
