VALUES ('doc-09-mitre-attack-p0-13748', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-12T21:40:00.267Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) has used the filename `systemd-daemon` in an attempt to appear legitimate.(Citation: netlab360 rotajakiro vs oceanlotus)", "external_references": [{"description": "Alex Turing. (2021, May 6). RotaJakiro, the Linux version of the OceanLotus. Retrieved June 14, 2023.", "source_name": "netlab360 rotajakiro vs oceanlotus", "url": "https://blog.netlab.360.com/rotajakiro_linux_version_of_oceanlotus/"}], "id": "relationship--ceadd093-d60f-452e-a145-671d010bba50", "modified": "2026-04-29T14:23:06.208Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13748', 0, 70, '09-mitre-attack', 'retrieved', 'A9ABB240A1BA11E7E144D33551B0FCAE052E1F26F27B42C0238E4684058EC96B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
