VALUES ('doc-09-mitre-attack-p0-13752', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-14T21:59:16.631Z", "description": "When executing with user-level permissions, [RotaJakiro](https://attack.mitre.org/software/S1078) can install persistence using a .desktop file under the `$HOME/.config/autostart/` folder.(Citation: RotaJakiro 2021 netlab360 analysis)", "external_references": [{"description": " Alex Turing, Hui Wang. (2021, April 28). RotaJakiro: A long live secret backdoor with 0 VT detection. Retrieved June 14, 2023.", "source_name": "RotaJakiro 2021 netlab360 analysis", "url": "https://blog.netlab.360.com/stealth_rotajakiro_backdoor_en/"}], "id": "relationship--ea61bd22-3ebc-4945-9b0a-60e65e3d4d64", "modified": "2026-04-29T14:23:06.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--e0232cb0-ded5-4c2e-9dc7-2893142a5c11", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13752', 0, 79, '09-mitre-attack', 'retrieved', '6B2FBE5516DAF2F037651271D49406F8471AC23F04A49DF2FE2562D56BC6B4EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
