VALUES ('doc-09-mitre-attack-p0-13753', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-21T16:33:59.457Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RotaJakiro](https://attack.mitre.org/software/S1078) sends device and other collected data back to the C2 using the established C2 channels over TCP. (Citation: RotaJakiro 2021 netlab360 analysis)", "external_references": [{"description": " Alex Turing, Hui Wang. (2021, April 28). RotaJakiro: A long live secret backdoor with 0 VT detection. Retrieved June 14, 2023.", "source_name": "RotaJakiro 2021 netlab360 analysis", "url": "https://blog.netlab.360.com/stealth_rotajakiro_backdoor_en/"}], "id": "relationship--efcc09fb-4c15-4a58-9bc5-b92747eae842", "modified": "2026-04-29T14:23:06.251Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--08e844a8-371f-4fe3-9d1f-e056e64a7fde", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13753', 0, 83, '09-mitre-attack', 'retrieved', 'BD9EDEBFB8DD43FD39F094055FE8FB618537CAA98BEB0084449D1F711FDF9484', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
