VALUES ('doc-09-mitre-attack-p0-13755', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-11T21:36:04.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AvosLocker](https://attack.mitre.org/software/S1053) has used a variety of Windows API calls, including `NtCurrentPeb` and `GetLogicalDrives`.(Citation: Malwarebytes AvosLocker Jul 2021)", "external_references": [{"description": "Hasherezade. (2021, July 23). AvosLocker enters the ransomware scene, asks for partners. Retrieved January 11, 2023.", "source_name": "Malwarebytes AvosLocker Jul 2021", "url": "https://www.malwarebytes.com/blog/threat-intelligence/2021/07/avoslocker-enters-the-ransomware-scene-asks-for-partners"}], "id": "relationship--1b0ca110-bb1d-434d-a271-6574fdb11723", "modified": "2026-04-29T14:23:05.941Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0945a1a5-a79a-47c8-9079-10c16cdfcb5d", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13755', 0, 71, '09-mitre-attack', 'retrieved', '5E91451937E138FD38D45F2DABDC4607EA96EE56EA7101118902F157092154C3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
