VALUES ('doc-09-mitre-attack-p0-13756', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-04-07T23:01:29.164Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AvosLocker](https://attack.mitre.org/software/S1053) can restart a compromised machine in safe mode.(Citation: Trend Micro AvosLocker Apr 2022)(Citation: Costa AvosLocker May 2022) ", "external_references": [{"description": "Costa, F. (2022, May 1). RaaS AvosLocker Incident Response Analysis. Retrieved January 11, 2023.", "source_name": "Costa AvosLocker May 2022", "url": "https://www.linkedin.com/pulse/raas-avoslocker-incident-response-analysis-fl%C3%A1vio-costa?trk=articles_directory"}, {"description": "Trend Micro Research. (2022, April 4). Ransomware Spotlight AvosLocker. Retrieved January 11, 2023.", "source_name": "Trend Micro AvosLocker Apr 2022", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-avoslocker"}], "id": "relationship--3b089236-9b2f-40ee-9230-6961de8a60be", "modified": "2026-04-29T14:23:06.002Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0945a1a5-a79a-47c8-9079-10c16cdfcb5d", "spec_version": "2.1", "target_ref": "attack-pattern--c7660f19-f8c5-4ae3-a5e5-24381c270376", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13756', 0, 93, '09-mitre-attack', 'retrieved', '8E01A4A01B08E3359D195228DCD90E1290349042CE772DD7ACC7AB7F1143FE26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
