VALUES ('doc-09-mitre-attack-p0-13757', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-11T21:24:22.601Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AvosLocker](https://attack.mitre.org/software/S1053) has encrypted files and network resources using AES-256 and added an `.avos`, `.avos2`, or `.AvosLinux` extension to filenames.(Citation: Malwarebytes AvosLocker Jul 2021)(Citation: Trend Micro AvosLocker Apr 2022)(Citation: Cisco Talos Avos Jun 2022)(Citation: Joint CSA AvosLocker Mar 2022)", "external_references": [{"description": "FBI, FinCEN, Treasury. (2022, March 17). Indicators of Compromise Associated with AvosLocker Ransomware. Retrieved January 11, 2023.", "source_name": "Joint CSA AvosLocker Mar 2022", "url": "https://www.ic3.gov/Media/News/2022/220318.pdf"}, {"description": "Hasherezade. (2021, July 23). AvosLocker enters the ransomware scene, asks for partners. Retrieved January 11, 2023.", "source_name": "Malwarebytes AvosLocker Jul 2021", "url": "https://www.malwarebytes.com/blog/threat-intelligence/2021/07/avoslocker-enters-the-ransomware-scene-asks-for-partners"}, {"description": "Trend Micro Research. (2022, April 4). Ransomware Spotlight AvosLocker. Retrieved January 11, 2023.", "source_name": "Trend Micro AvosLocker Apr 2022", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-avoslocker"}, {"description": "Venere, G. Neal, C. (2022, June 21). Avos ransomware group expands with new attack arsenal. Retrieved January 11, 2023.", "source_name": "Cisco Talos Avos Jun 2022", "url": "https://blog.talosintelligence.com/avoslocker-new-arsenal/"}], "id": "relationship--40861c0e-9cbc-4355-a7c0-cc0405c70b82", "modified": "2026-04-29T14:23:06.013Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0945a1a5-a79a-47c8-9079-10c16cdfcb5d", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13757', 0, 168, '09-mitre-attack', 'retrieved', 'C24AC1BFCEE0B375702EAE1B63ADE73E2E29E3E03E4B2DB84231C056F9B01899', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
