VALUES ('doc-09-mitre-attack-p0-13821', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-11T17:37:20.871Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MEDUSA](https://attack.mitre.org/software/S1220) is a rootkit with command execution and credential logging capabilities.(Citation: Google Cloud Mandiant UNC3886 2024)\n", "external_references": [{"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}], "id": "relationship--add8d076-83a4-44cf-8e4c-90caa144e488", "modified": "2026-04-29T14:23:06.162Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a615414-1dad-4131-802d-38f5d72ef852", "spec_version": "2.1", "target_ref": "attack-pattern--0f20e3cb-245b-4a61-8a91-2d93f7cb0e9b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13821', 0, 83, '09-mitre-attack', 'retrieved', '7D7109853EA97BED14E4B2C15070D3379E1AE8B128744159F73105B46768516C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
