VALUES ('doc-09-mitre-attack-p0-13822', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-11T17:32:56.647Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MEDUSA](https://attack.mitre.org/software/S1220) can execute code through dynamic linker hijacking of the `LD_PRELOAD` library.(Citation: Google Cloud Mandiant UNC3886 2024)", "external_references": [{"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}], "id": "relationship--bf655369-b813-41d7-8108-769d8f5088f1", "modified": "2026-04-29T14:23:06.187Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a615414-1dad-4131-802d-38f5d72ef852", "spec_version": "2.1", "target_ref": "attack-pattern--633a100c-b2c9-41bf-9be5-905c1b16c825", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13822', 0, 84, '09-mitre-attack', 'retrieved', 'D679247109F2A72EF6E81045E60B3D46A2695A29627695F904624C0EAF37C125', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
