VALUES ('doc-09-mitre-attack-p0-13823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-27T21:03:56.211Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VersaMem](https://attack.mitre.org/software/S1154) hooked and overrided Versa''s built-in authentication method, `setUserPassword`, to intercept plaintext credentials when submitted to the server.(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--15a63ae2-08d7-4771-9537-276835d7513f", "modified": "2026-04-29T14:23:05.933Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a6ec267-83a9-41a5-98c7-57c3ff81e11f", "spec_version": "2.1", "target_ref": "attack-pattern--f5946b5e-9408-485f-a7f7-b5efc88909b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13823', 0, 76, '09-mitre-attack', 'retrieved', 'B75E7400064C22D7842E078CC43572436C68CBF217E3AECD2B0FABBA8F6235E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
