VALUES ('doc-09-mitre-attack-p0-13826', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-27T21:09:32.328Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VersaMem](https://attack.mitre.org/software/S1154) deleted files related to initial installation such as temporary files related to the PID of the main web process.(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--8e29807a-833f-46cd-abfe-3133daa8f7fb", "modified": "2026-04-29T14:23:06.119Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a6ec267-83a9-41a5-98c7-57c3ff81e11f", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13826', 0, 78, '09-mitre-attack', 'retrieved', '9226CD977E5ADA72779366D100335E48816079F5A53B2EFB0474C33B9C71FE09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
