VALUES ('doc-09-mitre-attack-p0-13828', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-27T21:05:25.164Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VersaMem](https://attack.mitre.org/software/S1154) staged captured credentials locally at `/tmp/.temp.data`.(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--e86b2094-65ea-45f8-94cc-0467cf2eebd9", "modified": "2026-04-29T14:23:06.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a6ec267-83a9-41a5-98c7-57c3ff81e11f", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13828', 0, 65, '09-mitre-attack', 'retrieved', '8B3B868CDD4232246C2E11630AD1EE927B4A15DE6D4A7718F69A19AF4E78608C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
