VALUES ('doc-09-mitre-attack-p0-13829', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-27T21:08:37.911Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VersaMem](https://attack.mitre.org/software/S1154) hooked the Catalina application filter chain `doFilter` on compromised systems to monitor all inbound requests to the local Tomcat web server, inspecting them for parameters like passwords and follow-on Java modules.(Citation: Lumen Versa 2024)", "external_references": [{"description": "Black Lotus Labs. (2024, August 27). Taking The Crossroads: The Versa Director Zero-Day Exploitaiton. Retrieved August 27, 2024.", "source_name": "Lumen Versa 2024", "url": "https://blog.lumen.com/taking-the-crossroads-the-versa-director-zero-day-exploitation/"}], "id": "relationship--fc57736f-1142-4385-82a1-8baf6b6eedc6", "modified": "2026-04-29T14:23:06.267Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a6ec267-83a9-41a5-98c7-57c3ff81e11f", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13829', 0, 90, '09-mitre-attack', 'retrieved', 'E7747379DA9F6E524F425BDA2BF2815448C77F00EA6ADD782D8BAFECB1372E40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
