VALUES ('doc-09-mitre-attack-p0-13831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Power Loader](https://attack.mitre.org/software/S0177) overwrites Explorer’s Shell_TrayWnd extra window memory to redirect execution to a NTDLL function that is abused to assemble and execute a return-oriented programming (ROP) chain and create a malicious thread within Explorer.exe.(Citation: MalwareTech Power Loader Aug 2013)(Citation: WeLiveSecurity Gapz and Redyms Mar 2013)", "external_references": [{"description": "MalwareTech. (2013, August 13). PowerLoader Injection – Something truly amazing. Retrieved December 16, 2017.", "source_name": "MalwareTech Power Loader Aug 2013", "url": "https://www.malwaretech.com/2013/08/powerloader-injection-something-truly.html"}, {"description": "Matrosov, A. (2013, March 19). Gapz and Redyms droppers based on Power Loader code. Retrieved December 16, 2017.", "source_name": "WeLiveSecurity Gapz and Redyms Mar 2013", "url": "https://www.welivesecurity.com/2013/03/19/gapz-and-redyms-droppers-based-on-power-loader-code/"}], "id": "relationship--c56de8bc-ad9e-415a-8840-ae294ed4f88a", "modified": "2026-04-29T14:23:06.195Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0a9c51e0-825d-4b9b-969d-ce86ed8ce3c3", "spec_version": "2.1", "target_ref": "attack-pattern--0042a9f5-f053-4769-b3ef-9ad018dfa298", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13831', 0, 126, '09-mitre-attack', 'retrieved', '2450ABE830656E371846694BCDB7A9FF11A4446F8C8BCD64FD21350C3F5EF42E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type":