VALUES ('doc-09-mitre-attack-p0-13837', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-21T17:01:29.135Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Chinoxy](https://attack.mitre.org/software/S1041) can use a digitally signed binary (\"Logitech Bluetooth Wizard Host Process\") to load its dll into memory.(Citation: Bitdefender FunnyDream Campaign November 2020)", "external_references": [{"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "id": "relationship--05e15ff7-e0b1-47e3-a7bd-7f0e8845bf2c", "modified": "2026-04-29T14:23:05.911Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0b639373-5f03-430e-b8f9-2fe8c8faad8e", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13837', 0, 80, '09-mitre-attack', 'retrieved', '086DB7869D6FB4EEDFA69336E3297A7B81CB154E715BEA7C56E966F09AEB6A84', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
