VALUES ('doc-09-mitre-attack-p0-13838', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-21T17:04:31.204Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Chinoxy](https://attack.mitre.org/software/S1041) dropping function can initiate decryption of its config file.(Citation: Bitdefender FunnyDream Campaign November 2020)", "external_references": [{"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "id": "relationship--356aa4b0-e6c2-4ef7-a3b2-837c25c283b3", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0b639373-5f03-430e-b8f9-2fe8c8faad8e", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13838', 0, 73, '09-mitre-attack', 'retrieved', '73E0D001B5DC1591617AD36B645300E45936B1D5EA17ACF5B435E7A669FE1301', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
