VALUES ('doc-09-mitre-attack-p0-13873', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-16T17:07:21.541Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[COATHANGER](https://attack.mitre.org/software/S1105) copies the malicious file /data2/.bd.key/preload.so to /lib/preload.so , then launches a child process that executes the malicious file /data2/.bd.key/authd as /bin/authd with the arguments /lib/preload.so reboot newreboot 1 .(Citation: NCSC-NL COATHANGER Feb 2024) This injects the malicious preload.so file into the process with PID 1, and replaces its reboot function with the malicious newreboot function for persistence.", "external_references": [{"description": "Dutch Military Intelligence and Security Service (MIVD) & Dutch General Intelligence and Security Service (AIVD). (2024, February 6). Ministry of Defense of the Netherlands uncovers COATHANGER, a stealthy Chinese FortiGate RAT. Retrieved February 7, 2024.", "source_name": "NCSC-NL COATHANGER Feb 2024", "url": "https://www.ncsc.nl/binaries/ncsc/documenten/publicaties/2024/februari/6/mivd-aivd-advisory-coathanger-tlp-clear/TLP-CLEAR+MIVD+AIVD+Advisory+COATHANGER.pdf"}], "id": "relationship--89871b65-3850-440a-8a6b-4ed78a24b13d", "modified": "2026-04-29T14:23:06.113Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--0c242cc5-58d3-4fe3-a866-b00a4b6fb817", "spec_version": "2.1", "target_ref": "attack-pattern--633a100c-b2c9-41bf-9be5-905c1b16c825", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-13873', 0, 131, '09-mitre-attack', 'retrieved', '4D9A0C64ADF38B02A8D0B45A2423C9C7E15B7C2F0D92A52D2AD0B31F37F17B61', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "kno