VALUES ('doc-09-mitre-attack-p0-14046', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T21:03:28.352Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) will attempt to load non-existent DLLs in attempt to detect sandbox creation of a dummy DLL to prevent the program from crashing.(Citation: Palo Alto HeartCrypt DEC 2024)", "external_references": [{"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--339d80aa-dd56-47ca-8ce0-bb19a4a42502", "modified": "2026-04-29T14:23:05.987Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14046', 0, 83, '09-mitre-attack', 'retrieved', '7BFE4D685F52486ED5A3E5DD229C3D7D944B0DABB9BDC65D605033C88BE8C4B8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
