VALUES ('doc-09-mitre-attack-p0-14048', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T20:52:01.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) can pack malicious Windows x86 and .NET payloads in order to evade detection.(Citation: Palo Alto HeartCrypt DEC 2024)(Citation: Check Point Blind Eagle MAR 2025)\n", "external_references": [{"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--6901f3e3-6a46-4596-880d-341afff59aa1", "modified": "2026-04-29T14:23:06.068Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14048', 0, 106, '09-mitre-attack', 'retrieved', '513E643B3966D5BFF99FD26947997196D1EA377E6CEA1AE7EBD977D656E5AB67', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
