VALUES ('doc-09-mitre-attack-p0-14049', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T20:55:42.674Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) strings are encrypted via a single-byte XOR operation rotating over a hard-coded key, possibly provided by the PaaS customers. (Citation: Palo Alto HeartCrypt DEC 2024)", "external_references": [{"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--6bf5bf94-f5d8-48ca-9805-9ffb2ccdd551", "modified": "2026-04-29T14:23:06.072Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14049', 0, 81, '09-mitre-attack', 'retrieved', 'E9AC5FDA809A883B41C7E5A33389F2D79F5AC4E493104B8C8804A49E90C77D2F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
