VALUES ('doc-09-mitre-attack-p0-14050', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T21:27:58.901Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) can set the `CurrentVersion\\Run` key to establish persistence.(Citation: Palo Alto HeartCrypt DEC 2024)", "external_references": [{"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--8d204453-9efc-4e91-8385-5be0e038a7e3", "modified": "2026-04-29T14:23:06.118Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14050', 0, 69, '09-mitre-attack', 'retrieved', '0D81E9BE4F5681B3B56A371933781799AD0FC0C74C7C347B556DE82BE72E152C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
