VALUES ('doc-09-mitre-attack-p0-14051', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T21:31:06.391Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) can use the `reg add` command via `cmd.exe` for Registry modification.(Citation: Palo Alto HeartCrypt DEC 2024)", "external_references": [{"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--b3a53a04-3f86-4e42-9caa-34f554c6a868", "modified": "2026-04-29T14:23:06.171Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14051', 0, 72, '09-mitre-attack', 'retrieved', '3DE6AA836523B423CAA28DE2DB53F04CAC26005173EE05FC9CE93F57C02048CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
