VALUES ('doc-09-mitre-attack-p0-14052', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T20:59:42.017Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HeartCrypt](https://attack.mitre.org/software/S9018) can use Windows API functions to modify the Registry and `FindResourceW`, `LoadResource`, and `LockResource` to acquire a pointer to corresponding code resources.(Citation: Palo Alto HeartCrypt DEC 2024)", "external_references": [{"description": "Tujague, J., Bunce, D. (n.d.). Crypted Hearts: Exposing the HeartCrypt Packer-as-a-Service Operation. Retrieved April 16, 2026.", "source_name": "Palo Alto HeartCrypt DEC 2024", "url": "https://unit42.paloaltonetworks.com/packer-as-a-service-heartcrypt-malware/"}], "id": "relationship--bee2287d-9e33-4757-b6af-e0dba4a7bb14", "modified": "2026-04-29T14:23:06.186Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--148f947c-aabd-4ba8-b6a3-22b296855119", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14052', 0, 83, '09-mitre-attack', 'retrieved', '0A1CA9FE4EC204252935D79DA5F27023EA39EE1FB5D3CF286A7CE88ADA190C01', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
