VALUES ('doc-09-mitre-attack-p0-14056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-05T17:31:22.340Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ursnif](https://attack.mitre.org/software/S0386) has dropped payload and configuration files to disk. [Ursnif](https://attack.mitre.org/software/S0386) has also been used to download and execute additional payloads.(Citation: TrendMicro PE_URSNIF.A2)(Citation: TrendMicro BKDR_URSNIF.SM)", "external_references": [{"description": "Trend Micro. (2014, December 11). PE_URSNIF.A2. Retrieved June 5, 2019.", "source_name": "TrendMicro PE_URSNIF.A2", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/PE_URSNIF.A2?_ga=2.131425807.1462021705.1559742358-1202584019.1549394279"}, {"description": "Sioting, S. (2013, June 15). BKDR_URSNIF.SM. Retrieved June 5, 2019.", "source_name": "TrendMicro BKDR_URSNIF.SM", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/BKDR_URSNIF.SM?_ga=2.129468940.1462021705.1559742358-1202584019.1549394279"}], "id": "relationship--0d88d99d-88b0-4e49-b2c3-3607a32069ed", "modified": "2026-04-29T14:23:05.922Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1492d0f8-7e14-4af3-9239-bc3fe10d3407", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14056', 0, 86, '09-mitre-attack', 'retrieved', '1804A89203B948C948C855D3EBFAC558F8523FAA465ACBF2B9C0F73DFADCCED9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
