VALUES ('doc-09-mitre-attack-p0-14160', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Miner-C](https://attack.mitre.org/software/S0133) copies itself into the public folder of Network Attached Storage (NAS) devices and infects new victims who open the file.(Citation: Softpedia MinerC)", "external_references": [{"description": "Cimpanu, C.. (2016, September 9). Cryptocurrency Mining Malware Discovered Targeting Seagate NAS Hard Drives. Retrieved September 12, 2024.", "source_name": "Softpedia MinerC", "url": "https://news.softpedia.com/news/cryptocurrency-mining-malware-discovered-targeting-seagate-nas-hard-drives-508119.shtml"}], "id": "relationship--e0d33a40-a0d1-49fe-bea1-d0e4f000f628", "modified": "2026-04-29T14:23:06.232Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--17dec760-9c8f-4f1b-9b4b-0ac47a453234", "spec_version": "2.1", "target_ref": "attack-pattern--246fd3c7-f5e3-466d-8787-4c13d9e3b61c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14160', 0, 77, '09-mitre-attack', 'retrieved', '31A30B68F5B142C829F99FB2CCD9C1D6ABE9A28932E4B2487D926DC41071267C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
