VALUES ('doc-09-mitre-attack-p0-14164', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If the victim is using PowerShell 3.0 or later, [POWERSOURCE](https://attack.mitre.org/software/S0145) writes its decoded payload to an alternate data stream (ADS) named kernel32.dll that is saved in %PROGRAMDATA%\\Windows\\ .(Citation: Cisco DNSMessenger March 2017)", "external_references": [{"description": "Brumaghin, E. and Grady, C.. (2017, March 2). Covert Channels and Poor Decisions: The Tale of DNSMessenger. Retrieved March 8, 2017.", "source_name": "Cisco DNSMessenger March 2017", "url": "http://blog.talosintelligence.com/2017/03/dnsmessenger.html"}], "id": "relationship--bc838675-63af-45c5-9a30-081b5f5ac0d7", "modified": "2026-04-29T14:23:06.182Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--17e919aa-4a49-445c-b103-dbb8df9e7351", "spec_version": "2.1", "target_ref": "attack-pattern--f2857333-11d4-45bf-b064-2c28d8525be5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14164', 0, 91, '09-mitre-attack', 'retrieved', '0B14D0010CEEB69E7B1B346BE55EA3373156C24FE0F6735A8D58B1B23D0C1707', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
