VALUES ('doc-09-mitre-attack-p0-14174', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T14:38:48.189Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Tsundere Botnet](https://attack.mitre.org/software/S9034) has created a value in the `HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Run` Registry key, ensuring that it is run at login.(Citation: SecureListUbiedo_Tsundere_Nov2025)(Citation: CAL_MuddyWater_Mar2026) ", "external_references": [{"description": "Ctrl-Alt-Intel. (2026, March 4). MuddyWater Exposed: Inside an Iranian APT operation . Retrieved April 6, 2026.", "source_name": "CAL_MuddyWater_Mar2026", "url": "https://ctrlaltintel.com/research/MuddyWater/"}, {"description": "Ubiedo, L. (2025, November 20). Blockchain and Node.js abused by Tsundere: an emerging botnet. Retrieved April 6, 2026.", "source_name": "SecureListUbiedo_Tsundere_Nov2025", "url": "https://securelist.com/tsundere-node-js-botnet-uses-ethereum-blockchain/117979/"}], "id": "relationship--7118797d-8bb1-4404-8f00-d02113c7dd7d", "modified": "2026-04-29T14:23:06.080Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--18f5f8c6-bba5-4aba-93e7-3539fe565883", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14174', 0, 95, '09-mitre-attack', 'retrieved', '3EEC7FDC66C1788456B1DB2B9AC2F0D4536D3B3FA3E3F5329F2C0E13DF7AB56D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
