VALUES ('doc-09-mitre-attack-p0-14208', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T17:59:44.401Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zeus Panda](https://attack.mitre.org/software/S0330) collects the current system time (UTC) and sends it back to the C2 server.(Citation: GDATA Zeus Panda June 2017)", "external_references": [{"description": "Ebach, L. (2017, June 22). Analysis Results of Zeus.Variant.Panda. Retrieved November 5, 2018.", "source_name": "GDATA Zeus Panda June 2017", "url": "https://cyberwtf.files.wordpress.com/2017/07/panda-whitepaper.pdf"}], "id": "relationship--9494b0d8-26d9-48ae-8dd1-c9d8966b23a0", "modified": "2026-04-29T14:23:06.128Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--198db886-47af-4f4c-bff5-11b891f85946", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14208', 0, 73, '09-mitre-attack', 'retrieved', '266041FF9D25349E75D373DD53BF37194274C2C8D784F80B67D40E86D3873EFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
