VALUES ('doc-09-mitre-attack-p0-14209', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-18T19:24:12.200Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Zeus Panda](https://attack.mitre.org/software/S0330) queries the system''s keyboard mapping to determine the language used on the system. It will terminate execution if it detects LANG_RUSSIAN, LANG_BELARUSIAN, LANG_KAZAK, or LANG_UKRAINIAN.(Citation: Talos Zeus Panda Nov 2017)", "external_references": [{"description": "Brumaghin, E., et al. (2017, November 02). Poisoning the Well: Banking Trojan Targets Google Search Results. Retrieved November 5, 2018.", "source_name": "Talos Zeus Panda Nov 2017", "url": "https://blog.talosintelligence.com/2017/11/zeus-panda-campaign.html#More"}], "id": "relationship--a5cbd480-0147-4e70-9551-03a2b5b8fdcb", "modified": "2026-04-29T14:23:06.151Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--198db886-47af-4f4c-bff5-11b891f85946", "spec_version": "2.1", "target_ref": "attack-pattern--c1b68a96-3c48-49ea-a6c0-9b27359f9c19", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14209', 0, 91, '09-mitre-attack', 'retrieved', '3FE78DC6238BB23CA044DA11129DCED9D30144ED9E116805E23C19C9AD36DE4E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
