VALUES ('doc-09-mitre-attack-p0-14291', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GravityRAT](https://attack.mitre.org/software/S0237) collects the volumes mapped on the system, and also steals files with the following extensions: .docx, .doc, .pptx, .ppt, .xlsx, .xls, .rtf, and .pdf.(Citation: Talos GravityRAT)", "external_references": [{"description": "Mercer, W., Rascagneres, P. (2018, April 26). GravityRAT - The Two-Year Evolution Of An APT Targeting India. Retrieved May 16, 2018.", "source_name": "Talos GravityRAT", "url": "https://blog.talosintelligence.com/2018/04/gravityrat-two-year-evolution-of-apt.html"}], "id": "relationship--79d23451-095d-445d-a61e-3351b55eafde", "modified": "2026-04-29T14:23:06.092Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1d1fce2f-0db5-402b-9843-4278a0694637", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14291', 0, 84, '09-mitre-attack', 'retrieved', '8CC97CFC8CBBF8DBF493E0C560F691463B4BB95F9C111D212255B4D783576788', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
