VALUES ('doc-09-mitre-attack-p0-14297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-30T20:44:34.666Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GravityRAT](https://attack.mitre.org/software/S0237) has used HTTP over a non-standard port, such as TCP port 46769.(Citation: Talos GravityRAT)", "external_references": [{"description": "Mercer, W., Rascagneres, P. (2018, April 26). GravityRAT - The Two-Year Evolution Of An APT Targeting India. Retrieved May 16, 2018.", "source_name": "Talos GravityRAT", "url": "https://blog.talosintelligence.com/2018/04/gravityrat-two-year-evolution-of-apt.html"}], "id": "relationship--e61e5dc3-b6ac-4909-b188-eaede02385df", "modified": "2026-04-29T14:23:06.238Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1d1fce2f-0db5-402b-9843-4278a0694637", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14297', 0, 72, '09-mitre-attack', 'retrieved', '985A95679454B67C0EBF4BFBF372E80C0FCC3EA74A9EE1D3754C440E037834A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
