VALUES ('doc-09-mitre-attack-p0-14306', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-23T20:16:20.180Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Prestige](https://attack.mitre.org/software/S1058) can delete the backup catalog from the target system using: `c:\\Windows\\System32\\wbadmin.exe delete catalog -quiet` and can also delete volume shadow copies using: `\\Windows\\System32\\vssadmin.exe delete shadows /all /quiet`.(Citation: Microsoft Prestige ransomware October 2022)\n", "external_references": [{"description": "MSTIC. (2022, October 14). New “Prestige” ransomware impacts organizations in Ukraine and Poland. Retrieved January 19, 2023.", "source_name": "Microsoft Prestige ransomware October 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/10/14/new-prestige-ransomware-impacts-organizations-in-ukraine-and-poland/"}], "id": "relationship--61b0b64f-da02-4f36-949e-016b83fa747f", "modified": "2026-04-29T14:23:06.058Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1da748a5-875d-4212-9222-b4c23ab861be", "spec_version": "2.1", "target_ref": "attack-pattern--f5d8eed6-48a9-4cdf-a3d7-d1ffa99c3d2a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14306', 0, 89, '09-mitre-attack', 'retrieved', '528C1B4B35B0A64982971CF5C5267DC227E9280CD5BCBC6F257CFB4DC554F760', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
