VALUES ('doc-09-mitre-attack-p0-14320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-17T18:58:04.387Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisibleFerret](https://attack.mitre.org/software/S1245) has conducted keylogging using the Python project “pyWinHook” and \"Pyhook\".(Citation: Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024)(Citation: ESET Contagious Interview BeaverTail InvisibleFerret February 2025)(Citation: PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023) [InvisibleFerret](https://attack.mitre.org/software/S1245) has also captured keylogging thread checks for changes in an active window and key presses.(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024)", "external_references": [{"description": "eSentire Threat Response Unit (TRU). (2024, November 14). Bored BeaverTail & InvisibleFerret Yacht Club – A Lazarus Lure Pt.2. Retrieved October 17, 2025.", "source_name": "Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.esentire.com/blog/bored-beavertail-invisibleferret-yacht-club-a-lazarus-lure-pt-2"}, {"description": "Matej Havranek. (2025, February 20). DeceptiveDevelopment targets freelance developers. Retrieved October 17, 2025.", "source_name": "ESET Contagious Interview BeaverTail InvisibleFerret February 2025", "url": "https://www.welivesecurity.com/en/eset-research/deceptivedevelopment-targets-freelance-developers/"}, {"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}, {"description": "Unit 42. (2023, November 21). Hacking Employers and Seeking Employment: Two Job-Related Campaigns Bear Hallmarks of North Korean Threat Actors. Retrieved October 17, 2025.", "source_name": "PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023", "url": "https://unit42.paloaltonetworks.com/two-campaigns-by-north-korea-bad-actors-target-job-hunters/"}], "id": "relationship--6672498e-4e40-4f1a-b469-fa7fc05ee68a", "modified": "2026-04-29T14:23:06.064Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1dac60f2-7d53-4a3e-95d1-cb2e875d5491", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14320', 0, 207, '09-mitre-attack', 'retrieved', '4D4C5B87AF0202DF0F9176D5794EAFCC5ABC49FDBF42EAB0D413237DDA7BA8B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
