VALUES ('doc-09-mitre-attack-p0-14327', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T16:45:54.190Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisibleFerret](https://attack.mitre.org/software/S1245) has established persistence within GNOME-based Linux environments by placing entries within `.desktop` that run on Startup.(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024)", "external_references": [{"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}], "id": "relationship--a712140a-5e70-4d1b-9338-cc50eb0f3971", "modified": "2026-04-29T14:23:06.153Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1dac60f2-7d53-4a3e-95d1-cb2e875d5491", "spec_version": "2.1", "target_ref": "attack-pattern--e0232cb0-ded5-4c2e-9dc7-2893142a5c11", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14327', 0, 87, '09-mitre-attack', 'retrieved', '0BF642DCEB46504076B754D4F0AEE40C245EB2D023F10A6852D05BA4AAF837AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
