VALUES ('doc-09-mitre-attack-p0-14328', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-17T18:41:11.561Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisibleFerret](https://attack.mitre.org/software/S1245) has utilized remote access software including AnyDesk client through the “adc” module.(Citation: Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024)(Citation: ESET Contagious Interview BeaverTail InvisibleFerret February 2025)(Citation: PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023) [InvisibleFerret](https://attack.mitre.org/software/S1245) has also downloaded the AnyDesk client should it not already exist on the compromised host by searching for `C:/Program Files(x86)/AnyDesk/AnyDesk.exe`.(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024)", "external_references": [{"description": "eSentire Threat Response Unit (TRU). (2024, November 14). Bored BeaverTail & InvisibleFerret Yacht Club – A Lazarus Lure Pt.2. Retrieved October 17, 2025.", "source_name": "Esentire ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.esentire.com/blog/bored-beavertail-invisibleferret-yacht-club-a-lazarus-lure-pt-2"}, {"description": "Matej Havranek. (2025, February 20). DeceptiveDevelopment targets freelance developers. Retrieved October 17, 2025.", "source_name": "ESET Contagious Interview BeaverTail InvisibleFerret February 2025", "url": "https://www.welivesecurity.com/en/eset-research/deceptivedevelopment-targets-freelance-developers/"}, {"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}, {"description": "Unit 42. (2023, November 21). Hacking Employers and Seeking Employment: Two Job-Related Campaigns Bear Hallmarks of North Korean Threat Actors. Retrieved October 17, 2025.", "source_name": "PaloAlto ContagiousInterview BeaverTail InvisibleFerret November 2023", "url": "https://unit42.paloaltonetworks.com/two-campaigns-by-north-korea-bad-actors-target-job-hunters/"}], "id": "relationship--aeeb9a14-a1e8-4721-8e07-2f25a21f7fa6", "modified": "2026-04-29T14:23:06.163Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1dac60f2-7d53-4a3e-95d1-cb2e875d5491", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14328', 0, 214, '09-mitre-attack', 'retrieved', '95B1BB24D5B68B88EB02FDEBFA682772B712148BB78D376635C0D35F68497552', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
