VALUES ('doc-09-mitre-attack-p0-14338', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-19T16:46:34.431Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[InvisibleFerret](https://attack.mitre.org/software/S1245) has established persistence within Windows devices by creating a .bat file “queue.bat” within the Startup folder to run a Python script.(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024)", "external_references": [{"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}], "id": "relationship--daa688cf-80e7-4529-8456-332a7f42fa50", "modified": "2026-04-29T14:23:06.224Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1dac60f2-7d53-4a3e-95d1-cb2e875d5491", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14338', 0, 92, '09-mitre-attack', 'retrieved', '354247BBD4C75D02FC5E3A14850B85E25853CC1DFEA52146C2BAF52494349392', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
