VALUES ('doc-09-mitre-attack-p0-14381', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-04T18:17:05.631Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SharpDisco](https://attack.mitre.org/software/S1089) can identify recently opened files by using an LNK format parser to extract the original file path from LNK files found in either `%USERPROFILE%\\Recent` (Windows XP) or `%APPDATA%\\Microsoft\\Windows\\Recent` (newer Windows versions) .(Citation: MoustachedBouncer ESET August 2023)", "external_references": [{"description": "Faou, M. (2023, August 10). MoustachedBouncer: Espionage against foreign diplomats in Belarus. Retrieved September 25, 2023.", "source_name": "MoustachedBouncer ESET August 2023", "url": "https://www.welivesecurity.com/en/eset-research/moustachedbouncer-espionage-against-foreign-diplomats-in-belarus/"}], "id": "relationship--f5d2b140-1267-405b-8085-e02c135504f9", "modified": "2026-04-29T14:23:06.259Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--1fefb062-feda-484a-8f10-0cebf65e20e3", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-14381', 0, 91, '09-mitre-attack', 'retrieved', '114A42C879CDBF5297828A331AFD017AF78CF3AB5967E157D30780D25676BB1C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
